/**
 * import.js - AMD module to handle importing JSON via AJAX in a modal on the same page.
 *
 */
define(['jquery'], function($) {
    'use strict';

    /**
     * Initialize our import form handling.
     * @param {Object} config - Contains any config info we want (e.g. URL to post to).
     */
    function init(config) {
        // Grab the form by ID.
        var $form = $('#importForm');
        var $status = $('#importStatus');

        // Listen on form submission, intercept it, do AJAX with FormData.
        $form.on('submit', function(e) {
            e.preventDefault();

            // Clear previous status message, show 'loading...' or similar
            $status.html('<em>Importing...</em>');

            var formData = new FormData(this); // includes file input + sesskey
            $.ajax({
                url: config.importUrl,   // e.g. /admin/settings.php?section=xxx&action=importajax
                type: 'POST',
                data: formData,
                contentType: false,
                processData: false,

                success: function(response) {
                    try {
                        var data = JSON.parse(response);
                        if (data.status === 'ok') {
                            $status.html('<span style="color: green;">' + data.message + '</span>');
                            // Optionally close modal after a short delay or reload the page:
                            // setTimeout(function() { location.reload(); }, 1500);
                        } else {
                            $status.html('<span style="color: red;">Error: ' + data.message + '</span>');
                        }
                    } catch (err) {
                        // If the response isn't valid JSON, just display it
                        $status.html('<span style="color: red;">' + response + '</span>');
                    }
                },
                error: function(xhr) {
                    $status.html('<span style="color: red;">Upload error: ' + xhr.statusText + '</span>');
                }
            });
        });
    }

    // Return an object with init() so Moodle can call this as an AMD module.
    return {
        init: init
    };
});
